- [ ] 2. Check Wunderground for Syracuse, NY 7-day/10-day forecast to find lowest temp & day over next 7 days.
- [ ] 3. Open NWS forecast page for Rittman, OH (near Marshallville) in a new tab, inspect current forecast & active alerts (leave open).
- [ ] 4. Open NWS Mount Holly page in a new tab, check winter forecast graphic / snowfall amounts (leave open).
- [ ] 5. Summarize findings location-by-location and document open tabs.
`);

const tabId = 2052873101;
// Navigate or search directly on Google
await tool.navigate({ tabId, url: "https://www.google.com/search?q=Baltimore%2C+Maryland+weather" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

const text = await browser.read({ tabId, maxChars: 5000 });
console.log(text.text);

await edit({
  path: "tmp://sessions/channel%3Apanel%3A8e3f6fa9-97c6-47ee-82b2-d422202c7250/TODO.md",
  edits: [{
    oldText: "- [ ] 1. Search Google for \"Baltimore, Maryland weather\" and record current temp & condition.",
    newText: "- [x] 1. Search Google for \"Baltimore, Maryland weather\" and record current temp & condition. (79°F, Mostly cloudy)"
  }]
});

const tabId = 2052873101;
await tool.navigate({ tabId, url: "https://www.wunderground.com/forecast/us/ny/syracuse" });
const waitRes = await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });
console.log("Navigation result:", waitRes);

// Let's check the current URL and page content
const pageInfo = await browserjs(tabId, () => ({
  url: window.location.href,
  title: document.title,
  bodyTextSnippet: document.body.innerText.slice(0, 2000)
}));
console.log(pageInfo);

const tabId = 2052873101;
const forecastData = await browserjs(tabId, () => {
  // Let's grab the forecast cards or table rows
  const days = [];
  // Wunderground typically has day cards or rows
  const items = document.querySelectorAll('lib-forecast-chart, .forecast-wrap, .daily-card, table.twc-table tr, .card-body');
  // Or let's inspect the text of the 10-day forecast container
  const forecastContainer = document.querySelector('.forecast-wrap') || document.querySelector('lib-city-forecast') || document.querySelector('.city-forecast');
  return {
    containerSnippet: forecastContainer ? forecastContainer.innerText : "Not found",
    allText: document.body.innerText.substring(document.body.innerText.indexOf("Customize"), document.body.innerText.indexOf("ADDITIONAL CONDITIONS"))
  };
});
console.log(forecastData);

await edit({
  path: "tmp://sessions/channel%3Apanel%3A8e3f6fa9-97c6-47ee-82b2-d422202c7250/TODO.md",
  edits: [{
    oldText: "- [ ] 2. Check Wunderground for Syracuse, NY 7-day/10-day forecast to find lowest temp & day over next 7 days.",
    newText: "- [x] 2. Check Wunderground for Syracuse, NY 7-day/10-day forecast to find lowest temp & day over next 7 days. (Lowest: 46°F on Friday 9/18, also 46°F on Thu 9/24)"
  }]
});

// Create a new tab for NWS Rittman OH
const createRes = await tool.tabs_create({ url: "https://www.google.com/search?q=weather.gov+Rittman+OH+forecast" });
console.log("Created tab:", createRes);
const rittmanTabId = createRes.details.tabId;

await tool.wait_for({ tabId: rittmanTabId, condition: "load_state", value: "load" });

// Get search results to find the forecast.weather.gov link
const links = await browserjs(rittmanTabId, () => {
  return Array.from(document.querySelectorAll("a[href*='forecast.weather.gov']")).map(a => ({
    text: a.innerText,
    href: a.href
  }));
});
console.log("NWS links:", links);

const rittmanTabId = 2052873208;
const searchResults = await browserjs(rittmanTabId, () => {
  return Array.from(document.querySelectorAll("a")).map(a => ({
    text: a.innerText.trim(),
    href: a.href
  })).filter(a => a.href.includes("weather.gov") || a.text.includes("National Weather Service") || a.text.includes("Rittman"));
});
console.log(searchResults);

const rittmanTabId = 2052873208;

// Let's click the first search result for Rittman forecast
const clicked = await browserjs(rittmanTabId, () => {
  const anchors = Array.from(document.querySelectorAll("a"));
  const target = anchors.find(a => a.innerText.includes("7-Day Forecast 40.97N 81.77W") || a.innerText.includes("National Weather Service Rittman Forecast"));
  if (target) {
    target.click();
    return { clicked: true, text: target.innerText, href: target.href };
  }
  return { clicked: false };
});
console.log(clicked);

