const currentInfo = await browserjs(rittmanTabId, () => ({
  url: window.location.href,
  title: document.title
}));
console.log("Current page in tab 2052873208:", currentInfo);

const tabId = 2052873208;
await tool.navigate({ tabId, url: "https://forecast.weather.gov/MapClick.php?lat=40.9745&lon=-81.7796" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

const info = await browserjs(tabId, () => ({
  url: window.location.href,
  title: document.title,
  h2: document.querySelector('h2')?.innerText,
  location: document.querySelector('.panel-title')?.innerText || document.querySelector('#current-conditions')?.innerText
}));
console.log(info);

const tabId = 2052873208;

const forecastDetails = await browserjs(tabId, () => {
  // Let's check for hazard/alert banners
  const hazard = document.querySelector('.panel-danger') || document.querySelector('#headline-detail') || document.querySelector('.headline');
  // Current conditions
  const current_conditions = document.querySelector('#current_conditions_detail')?.innerText;
  const current_summary = document.querySelector('#current_conditions-summary')?.innerText;

  // Detailed forecast text
  const detailed = document.querySelector('#detailed-forecast')?.innerText;

  // 7-day forecast items
  const sevenDay = document.querySelector('#seven-day-forecast')?.innerText;

  // Location info
  const point = document.querySelector('#point-info')?.innerText;

  return {
    hazard: hazard ? hazard.innerText : "No hazard panel found",
    current_conditions,
    current_summary,
    point,
    detailed,
    sevenDay
  };
});

console.log(JSON.stringify(forecastDetails, null, 2));

const tabId = 2052873208;

const alertsCheck = await browserjs(tabId, () => {
  const alerts = document.querySelectorAll('.panel-danger, .headline, #headline, .alert, [class*="hazard"], [class*="alert"]');
  const alertTexts = Array.from(alerts).map(el => el.innerText.trim()).filter(Boolean);
  return {
    alertTexts,
    hasHazardWarining: document.body.innerText.includes("Hazardous Weather Outlook") || document.body.innerText.includes("Watch") || document.body.innerText.includes("Warning") || document.body.innerText.includes("Advisory"),
    allBanners: Array.from(document.querySelectorAll('.panel-heading, .panel-title, h1, h2, h3, h4')).map(e => e.innerText)
  };
});

console.log(alertsCheck);

