    oldText: "- [ ] 3. Open NWS forecast page for Rittman, OH (near Marshallville) in a new tab, inspect current forecast & active alerts (leave open).",
    newText: "- [x] 3. Open NWS forecast page for Rittman, OH (near Marshallville) in a new tab, inspect current forecast & active alerts (leave open in tab 2052873208). (No active alerts; partly cloudy 78°F, rain/thunderstorms over weekend)"
  }]
});

// Create a new tab for NWS Mount Holly
const mtHollyTab = await tool.tabs_create({ url: "https://www.weather.gov/phi" });
console.log("Created Mount Holly tab:", mtHollyTab);
const mtHollyTabId = mtHollyTab.details.tabId;

await tool.wait_for({ tabId: mtHollyTabId, condition: "load_state", value: "load" });

const pageInfo = await browserjs(mtHollyTabId, () => ({
  title: document.title,
  url: window.location.href,
  links: Array.from(document.querySelectorAll("a")).map(a => ({ text: a.innerText.trim(), href: a.href })).filter(a => a.text.toLowerCase().includes("winter") || a.href.toLowerCase().includes("winter") || a.text.toLowerCase().includes("snow"))
}));
console.log("Mount Holly links:", pageInfo);

const tabId = 2052873210;
await tool.navigate({ tabId, url: "https://www.weather.gov/phi/winter" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });

const winterPageInfo = await browserjs(tabId, () => {
  return {
    title: document.title,
    url: window.location.href,
    bodySnippet: document.body.innerText.slice(0, 3000),
    images: Array.from(document.querySelectorAll("img")).map(img => ({
      src: img.src,
      alt: img.alt,
      title: img.title
    }))
  };
});

console.log("Winter page info:", JSON.stringify(winterPageInfo, null, 2));

const tabId = 2052873210;

const details = await browserjs(tabId, () => {
  // Check the table content
  const tables = Array.from(document.querySelectorAll("table")).map(t => t.innerText);

  // Check the image source for expected snowfall
  const expectedImg = document.querySelector('img[title="Expected Snowfall - Official NWS Forecast"]');

  // Also check any text around expected snowfall
  const bodyText = document.body.innerText;
  const snowfallIndex = bodyText.indexOf("Snowfall Totals by Location");
  const snippet = snowfallIndex !== -1 ? bodyText.slice(snowfallIndex, snowfallIndex + 1500) : "Not found";

  return {
    tables,
    expectedImgSrc: expectedImg ? expectedImg.src : null,
    snippet
  };
});

console.log(details);

const tabId = 2052873210;

const winterAnalysis = await browserjs(tabId, () => {
  // Find the Expected Snowfall graphic element
  const expectedImg = document.querySelector('img[title="Expected Snowfall - Official NWS Forecast"]') || 
                      document.querySelector('img[alt*="Expected Snowfall"]');

  // Snowfall Totals table
  const snowTable = document.querySelector('#snowtable') || Array.from(document.querySelectorAll('table')).find(t => t.innerText.includes("Snowfall Totals by Location") || (t.innerText.includes("Expected") && t.innerText.includes("Low-End")));

  // Let's get the rows of the snow table
  let tableRows = [];
  if (snowTable) {
    tableRows = Array.from(snowTable.querySelectorAll('tr')).map(r => Array.from(r.querySelectorAll('th, td')).map(c => c.innerText.trim()));
  }

  // Check the parent link of the expectedImg if any
  const parentAnchor = expectedImg?.closest('a');

  return {
    imgSrc: expectedImg?.src,
    imgAlt: expectedImg?.alt,
    imgTitle: expectedImg?.title,
    parentLink: parentAnchor?.href,
    tableRowsPreview: tableRows.slice(0, 10),
    totalRows: tableRows.length
  };
});

console.log(winterAnalysis);

// Open the winter forecast graphic in a new tab
const graphicUrl = "https://www.wpc.ncep.noaa.gov/Prob_Precip/idss-map/mapgen.php?office=PHI&summary=true&pointpreferences=PHI&ptype=prob_sn&product=expected&2026091722";
const mapTab = await tool.tabs_create({ url: graphicUrl });
console.log("Opened map tab:", mapTab);
const mapTabId = mapTab.details.tabId;

await tool.wait_for({ tabId: mapTabId, condition: "load_state", value: "load" });

// Let's also check the tabs list using tabs_context
const currentTabs = await tool.tabs_context({ _: "" });
console.log("Current tabs context:", currentTabs);

// Close the duplicate tab 2052873209
await tool.tabs_close({ tabId: 2052873209 });

// Update TODO.md
await edit({
  path: "tmp://sessions/channel%3Apanel%3A8e3f6fa9-97c6-47ee-82b2-d422202c7250/TODO.md",
