    oldText: "- [ ] 4. Open NWS Mount Holly page in a new tab, check winter forecast graphic / snowfall amounts (leave open).",
    newText: "- [x] 4. Open NWS Mount Holly page in a new tab, check winter forecast graphic / snowfall amounts (leave open in tabs 2052873210 and 2052873211). (Expected snowfall: 0 inches across the entire region)"
  }]
});

const tabs = await tool.tabs_context({ _: "" });
console.log("Current remaining tabs:", tabs);

await edit({
  path: "tmp://sessions/channel%3Apanel%3A8e3f6fa9-97c6-47ee-82b2-d422202c7250/TODO.md",
  edits: [{
    oldText: "- [ ] 5. Summarize findings location-by-location and document open tabs.",
    newText: "- [x] 5. Summarize findings location-by-location and document open tabs."
  }]
});

const finalTabs = await tool.tabs_context({ _: "" });
console.log("Final tab listing:", finalTabs);

