const winterAnalysis = await browserjs(tabId, () => {
  // Find the Expected Snowfall graphic element
  const expectedImg = document.querySelector('img[title="Expected Snowfall - Official NWS Forecast"]') || 
                      document.querySelector('img[alt*="Expected Snowfall"]');

  // Snowfall Totals table
  const snowTable = document.querySelector('#snowtable') || Array.from(document.querySelectorAll('table')).find(t => t.innerText.includes("Snowfall Totals by Location") || (t.innerText.includes("Expected") && t.innerText.includes("Low-End")));

  // Let's get the rows of the snow table
  let tableRows = [];
  if (snowTable) {
    tableRows = Array.from(snowTable.querySelectorAll('tr')).map(r => Array.from(r.querySelectorAll('th, td')).map(c => c.innerText.trim()));
  }

  // Check the parent link of the expectedImg if any
  const parentAnchor = expectedImg?.closest('a');

  return {
    imgSrc: expectedImg?.src,
    imgAlt: expectedImg?.alt,
    imgTitle: expectedImg?.title,
    parentLink: parentAnchor?.href,
    tableRowsPreview: tableRows.slice(0, 10),
    totalRows: tableRows.length
  };
});

console.log(winterAnalysis);

